// [S4] Three-portal family features — dashboard, appointments, join, my doctor, invitations.
import 'package:family_veda/models/appointment.dart';
import 'package:family_veda/models/doctor_summary.dart';
import 'package:family_veda/models/family_doctor_request.dart';
import 'package:family_veda/models/family_dashboard.dart';
import 'package:family_veda/models/family_invitation.dart';
import 'package:family_veda/models/incoming_invitation.dart';
import 'package:family_veda/models/join_request.dart';
import 'package:family_veda/providers/core_providers.dart';
import 'package:family_veda/services/api/family_portal_api.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

final familyPortalApiProvider = Provider<FamilyPortalApi>(
  (ref) => DioFamilyPortalApi(ref.watch(apiClientProvider)),
);

final familyDashboardProvider = FutureProvider.autoDispose<FamilyDashboard>(
  (ref) => ref.watch(familyPortalApiProvider).getFamilyDashboard(),
);

final myAppointmentsProvider = FutureProvider.autoDispose<List<Appointment>>(
  (ref) => ref.watch(familyPortalApiProvider).getMyAppointments(),
);

final pendingJoinRequestsProvider = FutureProvider.autoDispose
    .family<List<JoinRequest>, String>(
      (ref, familyId) =>
          ref.watch(familyPortalApiProvider).getPendingJoinRequests(familyId),
    );

/// Invitations sent to the signed-in user's own email (any family user, not only Heads).
final incomingInvitationsProvider =
    FutureProvider.autoDispose<List<IncomingInvitation>>(
      (ref) => ref.watch(familyPortalApiProvider).getIncomingInvitations(),
    );

final familySentInvitationsProvider = FutureProvider.autoDispose
    .family<List<FamilyInvitationSummary>, String>(
      (ref, familyId) =>
          ref.watch(familyPortalApiProvider).getInvitations(familyId),
    );

final familyDoctorProvider = FutureProvider.autoDispose
    .family<DoctorSummary?, String>(
      (ref, familyId) => ref.watch(familyPortalApiProvider).getFamilyDoctor(familyId),
    );

final familyDoctorPendingRequestProvider = FutureProvider.autoDispose
    .family<FamilyDoctorRequest?, String>(
      (ref, familyId) => ref
          .watch(familyPortalApiProvider)
          .getPendingDoctorRequest(familyId),
    );

final doctorDirectorySearchProvider = StateProvider.autoDispose<String>((ref) => '');

final doctorDirectoryProvider = FutureProvider.autoDispose<List<DoctorSummary>>(
  (ref) {
    final search = ref.watch(doctorDirectorySearchProvider);
    return ref.watch(familyPortalApiProvider).searchDoctorDirectory(search: search);
  },
);
